{
  "bioavailability_prediction": "low",
  "confidence": "moderate",
  "revision_action": "flip",
  "supportive_card_ids": ["C177", "C186", "C195", "C205", "C188"],
  "contradictory_card_ids": ["C161", "C131", "C136", "C209", "C180"],
  "prediction_basis_card_ids": ["C177", "C186", "C195", "C205", "C188"],
  "claims": [
    {
      "claim": "L5 gut-wall efflux assays show that lipophilic steroids bearing ketone/hydroxyl groups can be P-gp/BCRP substrates: estrone (efflux ratio ~6.6, collapsed to 1.2 with GG918), ethinylestradiol (efflux ratio ~11, collapsed to 1.2), estriol (efflux ratio ~3.2, collapsed to 1.3), and estrone-3-sulfate (BCRP-mediated). The query is a lipophilic steroid with a 17-ketone and an enolizable 4-hydroxy-3-keto system, making gut-wall efflux a plausible presystemic loss mechanism.",
      "card_ids": ["C177", "C186", "C195", "C205"]
    },
    {
      "claim": "Budesonide, a high-permeability steroid with no P-gp efflux, shows ketoconazole-sensitive intestinal metabolism, demonstrating that high permeability does not preclude substantial gut-wall first-pass loss for steroids.",
      "card_ids": ["C188"]
    },
    {
      "claim": "The L4 high prediction relied on permeability/absorption of related steroids (e.g., exemestane, progesterone), but L5 shows that permeability evidence alone is insufficient to establish F >= 20% when gut-wall efflux/metabolism can dominate; for this steroid class, presystemic loss is coherent and the threshold is not affirmatively met.",
      "card_ids": ["C161", "C131", "C177", "C188"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "gut_wall_efflux_intestinal_metabolism",
      "applicability": "moderate",
      "direction": "contradictory",
      "decision_effect": "changed",
      "card_ids": ["C177", "C186", "C195", "C205", "C188"]
    }
  ],
  "evidence_gaps": [
    "No direct oral bioavailability measurement for the query molecule.",
    "No matched oral vs IV AUC data for the query.",
    "No direct P-gp/efflux assay for the query; transfer from estrone/estriol/EE is structural analogy.",
    "No direct intestinal or hepatic first-pass metabolism data for the query.",
    "No measured aqueous solubility for the query; inferred from logP and ionization.",
    "No dose or formulation specified for the query."
  ],
  "decision_summary": "L5 gut-wall efflux/intestinal-metabolism evidence shows that lipophilic steroids with ketone/hydroxyl groups can undergo P-gp/BCRP-mediated efflux (estrone, ethinylestradiol, estriol, estrone-3-sulfate) and that high-permeability steroids can still have substantial gut-wall metabolism (budesonide). The query is a 4-hydroxyandrostenedione-type steroid with a 17-ketone and enolizable 3-keto-4-enol system, making presystemic loss likely. The L4 high prediction based on permeability is therefore overturned; F >= 20% is not affirmatively supported. Flip to low with moderate confidence."
}

